def calculator(a: float, b: float, operator: str) -> str:
    try:
        if operator == "+":
            return str(a + b)
        elif operator == "-":
            return str(a - b)
        elif operator == "*":
            return str(a * b)
        elif operator == "/":
            if b == 0:
                return "Error: Division by zero"
            return str(a / b)
        else:
            return "Error: Invalid operator. Please use +, -, *, or /"
    except Exception as e:
        return f"Error: {str(e)}"

import json

def save_to_crm(feedback_text: str, sentiment: str, category: str, customer_tier: str, human_notes: str = "N/A"):
    log_entry = {
        "text": feedback_text,
        "sentiment": sentiment,
        "category": category,
        "customer_tier": customer_tier
, "human_notes": human_notes
    }
    try:
        with open("crm_demo_log.txt", "a") as f:
            f.write(json.dumps(log_entry) + "\n")
        return f"Log entry created successfully: {json.dumps(log_entry)}"
    except Exception as e:
        return f"Failed to write to CRM log: {str(e)}"

